import React from 'react';
/** One form renderer; current-status and recorded-event adapters own their
 * existing, separately validated commands. Rendering never mutates a log. */
export default function DutyForm({mode='current',title,context,onClose,onDelete,time,selection,location,equipment,load,notes,extras,footer,className=''}) {
  return <div className={`dd-root driver-duty-form ${className}`} data-duty-form="unified" data-duty-mode={mode}>
    <header className="dd-header sheet-head status-page-head driver-picker-head">
      <button type="button" aria-label="Back" onClick={onClose}>‹</button>
      <div><b>{title}</b><small>{context}</small></div>
      {onDelete?<button type="button" aria-label="Event actions" onClick={onDelete}>⋮</button>:<span/>}
    </header>
    <div className="dd-body form editor-form-v85 status-page-body driver-picker-body">
      <div className="dd-time-block" data-duty-section="time">{time}</div>
      {selection}
      <div data-duty-section="location">{location}</div>
      {equipment?<div data-duty-section="equipment">{equipment}</div>:null}
      {load?<div data-duty-section="load">{load}</div>:null}
      {notes?<div data-duty-section="notes">{notes}</div>:null}
      {extras}
    </div>
    <footer className="dd-footer compact-editor-footer-v111">{footer}</footer>
  </div>;
}
export function DutyFieldGrid({fields=[],children}) {
  return <div className="dd-fields driver-load-grid">{fields.map(field=><label key={field.key||field.label}>
    <span>{field.label}</span><input aria-label={field.label} value={field.value??''} onChange={e=>field.onChange?.(e.target.value)} readOnly={!field.onChange} autoComplete="off" placeholder={field.placeholder||''}/>
    {field.hint?<small>{field.hint}</small>:null}
  </label>)}{children}</div>;
}
export function DutySection({title,detail,children}) {
  return <section className="dd-field picker-section form-section"><div className="dd-field-head picker-label-row"><strong>{title}</strong>{detail?<span>{detail}</span>:null}</div>{children}</section>;
}

