import React from 'react';
import {DutySection} from './DutyForm.jsx';
/** Shared controlled location input. Callers cancel late GPS and preserve
 * manually typed drafts; recorded mode never requests GPS automatically. */
export default function DutyLocation({value,onChange,onCommit,onClear,onGps,gpsStatus='',suggestions=[],onSuggestion,mode='current',placeholder='City, ST',children}) {
  return <DutySection title="Location" detail={mode==='recorded'?'Recorded event location':'Current status location'}>
    {mode==='recorded'?<p className="dd-help">This location belongs to the recorded event. Current GPS is your position now.</p>:null}
    <div className="dd-location location-one-v85 location-editable-v91 driver-location-row gps-location-row location-row">
      <button type="button" className="gps-locate-btn" aria-label="Use GPS location" onClick={onGps}>⌖</button>
      <input aria-label="Location" value={value} onFocus={e=>e.currentTarget.select()} onClick={e=>e.currentTarget.select()} onChange={e=>onChange(e.target.value)} onBlur={()=>onCommit?.(value)} placeholder={placeholder} autoComplete="off" inputMode="text"/>
      <button type="button" className="location-clear-btn" aria-label="Clear location" onClick={onClear}>×</button>
    </div>
    {suggestions.length?<div className="driver-location-suggestions editor-location-suggestions">{suggestions.map(v=><button type="button" key={v} onClick={()=>onSuggestion?.(v)}>{v}</button>)}</div>:null}
    {gpsStatus?<p role="status" className="dd-help gps-hint gps-msg gps-v85">{gpsStatus}</p>:null}
    {children}
  </DutySection>;
}

