import React from 'react';
import {DUTY_STATUSES} from './dutyActivities.js';
export default function DutySelection({status,onStatusChange,activities=[],selected=[],onActivityChange,mode='current',day=''}) {
 const options=[...new Set([...activities,...selected])];
 return <div className="dd-selection" data-duty-mode={mode}>
  <section className="dd-field picker-section form-section" aria-label="Duty status"><div className="dd-field-head"><strong>Duty status</strong><span>{DUTY_STATUSES.find(v=>v.id===status)?.label||status}</span></div>
   <div className="dd-status-grid editor-duty-grid duty-grid driver-duty-grid" role="group" aria-label="Duty status">
    {DUTY_STATUSES.map(item=><button type="button" key={item.id} data-status={item.id} aria-label={item.id} aria-pressed={status===item.id} className={status===item.id?'picked':''} onClick={()=>onStatusChange(item.id)}><b>{item.id}</b><small>{item.label}</small></button>)}
   </div>
  </section>
  {!!options.length&&<section className="dd-field picker-section form-section editor-on-duty-reasons quick-activities-v11023" aria-label="Quick on duty activities">
   <div className="dd-field-head"><strong>Activity</strong><span>Select one or more</span></div>
   <div className="dd-activity-grid reason-pills driver-reason-grid multi-reason-grid">{options.map(reason=><button type="button" title={reason} key={reason} aria-label={reason} aria-pressed={selected.includes(reason)} className={selected.includes(reason)?'picked':''} onClick={()=>onActivityChange(reason)}>{reason}</button>)}</div>
  </section>}
 </div>;
}
